function isDarkHex(hex: string): boolean {
  const r = Number.parseInt(hex.slice(0, 2), 16)
  const g = Number.parseInt(hex.slice(2, 4), 16)
  const b = Number.parseInt(hex.slice(4, 6), 16)
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 < 0.3
}

/**
 * Renders a small brand mark for a stack/tool name, e.g. in the works
 * detail meta line or the about section's skills list. Returns null
 * when no icon is mapped for the given name.
 */
export function StackIcon({
  name,
  className,
}: {
  name: string
  className?: string
}): ReactNode {
  if (name === "Nuqs") {
    return (
      <svg
        viewBox="0 0 1024 1024"
        aria-hidden="true"
        className={cn("size-3.5 shrink-0 rounded-[3px] dark:invert", className)}
      >
        <rect width="1024" height="1024" rx="512" fill="#000" />
        <path d={NUQS_PATH} fill="#fff" />
      </svg>
    )
  }

  const icon = BRAND_ICONS[name]
  if (!icon) return null

  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      style={{ fill: `#${icon.hex}` }}
      className={cn(
        "size-3.5 shrink-0",
        isDarkHex(icon.hex) && "dark:invert",
        className
      )}
    >
      <path d={icon.path} />
    </svg>
  )
}
